package com.agriconnect.rescue;
import java.util.Map;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.stereotype.Component;import org.springframework.web.client.*;
@Component class CropClient{private final RestClient client;private final String key;CropClient(RestClient.Builder b,@Value("${crop-service.url}")String url,@Value("${internal.api-key}")String k){client=b.baseUrl(url).build();key=k;}Map<String,Object>batch(long id){try{return client.get().uri("/internal/crop-batches/{id}",id).header("X-Internal-Api-Key",key).retrieve().body(Map.class);}catch(HttpClientErrorException.NotFound e){throw new DomainException(HttpStatus.NOT_FOUND,"CROP_BATCH_NOT_FOUND","Crop batch not found");}catch(RestClientException e){throw new DomainException(HttpStatus.SERVICE_UNAVAILABLE,"DOWNSTREAM_SERVICE_UNAVAILABLE","Crop service is currently unavailable");}}}
